async function cbWidgetAction(event) {
  handleLog('cbWidgetAction', event);
  let event_type = '';
  if(!!event.Type) event_type = event.Type.toLowerCase();
  if(event_type === 'pressed')  return;

  switch(event.WidgetId) {
