function resetCameraMode() {
  console.log('Call ended: Resetting camera tracking to BestOverview.');

  xapi.Config.Cameras.SpeakerTrack.DefaultBehavior.set('BestOverview')
    .then(() => {
      console.log('Camera mode successfully reset to BestOverview.');
    })
    .catch((error) => {
      // If 'BestOverview' fails, it may be because the device uses 'Auto' or 'Frames'
      console.error('Failed to set SpeakerTrack Mode. Error:', error.message);
    });
}

