import xapi from 'xapi';

const PANEL_ID = 'room_controls';

// A valid, safe macro for testing - should show "No issues detected"

async function toggleMute() {
  try {
    await xapi.Command.Audio.Microphones.ToggleMute();
    console.log('Mute toggled');
  } catch (error) {
    console.error('Failed to toggle mute:', error);
  }
}

async function setVolume(level) {
  if (level < 0 || level > 100) {
    console.warn('Volume must be between 0 and 100');
    return;
  }
  await xapi.Command.Audio.Volume.Set({ Level: level });
}

async function getRoomInfo() {
  const name = await xapi.Config.UserInterface.ContactInfo.Name.get();
  const number = await xapi.Config.UserInterface.ContactInfo.ContactMethod.Number.get();
  return { name, number };
}

function init() {
  xapi.Event.UserInterface.Extensions.Panel.Clicked.on(event => {
    if (event.PanelId === PANEL_ID) {
      toggleMute();
    }
  });

  xapi.Event.UserInterface.Extensions.Widget.Action.on(event => {
    if (event.WidgetId === 'volume_slider' && event.Type === 'released') {
      setVolume(parseInt(event.Value, 10));
    }
  });

  console.log('Room controls macro initialized');
}

